import{_ as e,o as t,c as n,a0 as s}from"./chunks/framework.Bogozrur.js";const c=JSON.parse('{"title":"Why AAYU?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/why-aayu.md","filePath":"guide/why-aayu.md"}'),o={name:"guide/why-aayu.md"};function i(l,a,r,p,d,u){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="why-aayu" tabindex="-1">Why AAYU? <a class="header-anchor" href="#why-aayu" aria-label="Permalink to &quot;Why AAYU?&quot;">​</a></h1><p>Programming languages shouldn&#39;t feel like speaking to a machine. They should feel like giving instructions to an assistant.</p><p>AAYU was built with one simple philosophy: <strong>Code should be read like a story.</strong></p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Most modern web frameworks require you to understand:</p><ol><li>Complex syntax and boilerplate (e.g., <code>async/await</code>, <code>Promises</code>, <code>Interfaces</code>)</li><li>Context switching between backend languages (Python/Node) and frontend logic.</li><li>Obscure routing mechanisms and hidden state.</li></ol><h2 id="the-aayu-solution" tabindex="-1">The AAYU Solution <a class="header-anchor" href="#the-aayu-solution" aria-label="Permalink to &quot;The AAYU Solution&quot;">​</a></h2><p>AAYU completely removes these barriers:</p><h3 id="_1-human-readable-syntax" tabindex="-1">1. Human Readable Syntax <a class="header-anchor" href="#_1-human-readable-syntax" aria-label="Permalink to &quot;1. Human Readable Syntax&quot;">​</a></h3><p>Instead of writing <code>function calculateTax(amount) { return amount * 0.2; }</code>, you write:</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task calculate_tax with amount.</span></span>
<span class="line"><span>    return amount * 0.2.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><p>It feels natural. It reads top-to-bottom.</p><h3 id="_2-built-in-web-runtime" tabindex="-1">2. Built-in Web Runtime <a class="header-anchor" href="#_2-built-in-web-runtime" aria-label="Permalink to &quot;2. Built-in Web Runtime&quot;">​</a></h3><p>AAYU is not just a language; it is an <strong>Application Platform</strong>. You don&#39;t need to install Express, Flask, or Django.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>serve on 8080.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get &quot;/hello&quot; to handler.</span></span>
<span class="line"><span>    render text &quot;Hello World!&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="_3-ai-agent-friendly" tabindex="-1">3. AI Agent Friendly <a class="header-anchor" href="#_3-ai-agent-friendly" aria-label="Permalink to &quot;3. AI Agent Friendly&quot;">​</a></h3><p>Because AAYU&#39;s syntax maps so closely to natural English intent, <strong>AI Agents (like Claude, GPT, and Gemini) are exceptionally good at writing AAYU code.</strong></p><p>When you prompt an AI to &quot;write a loop that adds numbers&quot;, AAYU&#39;s syntax is often closer to the prompt itself than Python or JavaScript.</p><p><a href="/guide/ai-agents.html">Learn how to build AAYU apps with AI Agents →</a></p>`,19)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
